function applyServerState(data) {
  hydrateCanvas(data.canvas || state.canvas);
  renderBeats(data.coverage?.beats || []);
  if (data.phase==='error') {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    $('progress').hidden = true;
    $('output').hidden = true;
    $('toolbar').hidden = false;
    $('compose-error').textContent = data.error || 'Die Videoverarbeitung ist fehlgeschlagen.';
    $('compose-error').hidden = false;
    return true;
  }
  if (data.phase === 'review') {
    state.uploading = false;
    state.recommendationsStatus = data.recommendations_status || 'complete';
    state.pollingRecommendations = data.recommendations_status === 'pending';
