    $('export-davinci').href = data.davinci_url || data.resolve_url || data.export_url || '#';
    return true;
  }
  if (data.phase === 'working') {
    state.uploading = true;
    state.pollingRecommendations = false;
    $('progress').hidden = false;
    $('chunk-review').hidden = true;
    $('output').hidden = true;
    $('toolbar').hidden = false;
    const score = Math.round((data.coverage?.score || 0) * 100);
