    height: 2px;
    width: 100%;
    background: var(--border);
    position: relative;
    overflow: hidden;
    border-radius: 1px;
    margin-bottom: 16px;
  }
  .progress-line::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    width: var(--progress-value, 8%);
    background: var(--ink);
    transition: width 320ms ease;
  }
  .progress-copy {
    font-size: 13px;
    color: var(--muted);
  }

  /* Persistent status surface for long-running video jobs. */
  .job-status-card {
    position: fixed;
    top: 80px;
    right: 24px;
    width: min(360px, calc(100vw - 32px));
    padding: 18px;
    background: rgba(255, 255, 255, 0.98);
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 18px 48px rgba(17, 18, 20, 0.14);
    z-index: 130;
  }
  .job-status-card[hidden] { display: none; }
  .job-status-head {
    display: flex;
    align-items: flex-start;
    gap: 11px;
  }
  .job-status-indicator {
    width: 10px;
    height: 10px;
    margin-top: 5px;
    border-radius: 50%;
    flex: 0 0 auto;
    background: #d89b24;
    box-shadow: 0 0 0 4px #fff5d8;
  }
  .job-status-card[data-tone="active"] .job-status-indicator {
    background: #2563eb;
    box-shadow: 0 0 0 4px #e5edff;
  }
  .job-status-card[data-tone="success"] .job-status-indicator {
    background: #16824b;
    box-shadow: 0 0 0 4px #def5e8;
  }
  .job-status-card[data-tone="error"] .job-status-indicator {
    background: #c93838;
    box-shadow: 0 0 0 4px #fde7e7;
  }
  .job-status-body { min-width: 0; flex: 1; }
  .job-status-title {
    margin: 0;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: -0.01em;
  }
  .job-status-detail {
    margin: 4px 0 0;
    color: var(--muted);
    font-size: 12px;
    line-height: 1.45;
  }
  .job-status-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 16px;
    color: var(--muted);
    font-size: 11px;
  }
  .job-status-meta strong { color: var(--ink); font-weight: 600; }
  .job-status-progress {
    height: 4px;
    margin-top: 8px;
    overflow: hidden;
    border-radius: 999px;
    background: #eceef1;
  }
  .job-status-progress span {
    display: block;
    width: var(--job-progress, 8%);
    height: 100%;
    border-radius: inherit;
    background: var(--ink);
    transition: width 320ms ease;
  }
  .beats {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-top: 16px;
  }
  .beat {
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 3px;
    border: 1px solid var(--border);
    color: var(--muted);
  }
  .beat[data-status="covered"] {
    background: var(--ink);
    color: #ffffff;
    border-color: var(--ink);
  }

  .agent-status-message {
    margin-top: 16px;
    padding: 10px 12px;
    border: 1px solid #f3dfb0;
    border-radius: 6px;
          <div class="agent-row-name">A2 Director <span class="agent-row-status" id="status-director">bereit</span></div>
          <div class="agent-row-role">Regie, Hook, Sprechtempo & Videoaufbau</div>
        </div>
      </div>
      <div class="agent-row">
        <div class="agent-row-dot" style="background: var(--strategist);"></div>
        <div class="agent-row-info">
          <div class="agent-row-name">A3 Strategist <span class="agent-row-status" id="status-strategist">bereit</span></div>
          <div class="agent-row-role">Pitch-Story, harte Zahlen & Nutzenargumente</div>
        </div>
      </div>
      <div class="agent-row">
        <div class="agent-row-dot" style="background: var(--supervisor);"></div>
        <div class="agent-row-info">
          <div class="agent-row-name">A1 Supervisor <span class="agent-row-status" id="status-supervisor">bereit</span></div>
          <div class="agent-row-role">Script-Struktur, Wortgrenzen & Beat-Kopplung</div>
        </div>
      </div>
    </div>
  </div>
</header>

<aside id="job-status-card" class="job-status-card" data-tone="active" role="status" aria-live="polite" hidden>
  <div class="job-status-head">
    <span class="job-status-indicator" aria-hidden="true"></span>
    <div class="job-status-body">
      <h2 id="job-status-title" class="job-status-title">Videoauftrag gestartet</h2>
      <p id="job-status-detail" class="job-status-detail">Der Auftrag wird vorbereitet.</p>
    </div>
  </div>
  <div class="job-status-meta">
    <span>Geschätzte Restzeit</span>
    <strong id="job-status-eta">ca. 6–10 Min.</strong>
  </div>
  <div id="job-status-progress" class="job-status-progress" role="progressbar" aria-label="Fortschritt der Videoerstellung" aria-valuemin="0" aria-valuemax="100" aria-valuenow="8">
    <span></span>
  </div>
</aside>

<main>
  <div class="canvas-wrapper">
    <!-- Flowing Display Layer: Renders real text before + grey ghost text + real text after (natively shifted) -->
    <div id="canvas-display" class="canvas-display" aria-hidden="true"></div>

    <!-- Active Textarea -->
    <textarea id="prompt" class="prompt" aria-label="Beschreibe dein Video" placeholder="Was möchtest du erzählen? Schreibe frei drauflos..."></textarea>

    <!-- Collaborative Dynamic Cursors & Floating Advice Layer -->
    <div class="cursors-layer" id="cursors-layer">
      <!-- Director Cursor & (i) Info Badge -->
      <div id="cursor-director" class="agent-cursor director visible">
        <div class="cursor-header-wrap">
          <div class="cursor-header">A2 · Director</div>
          <div id="info-badge-director" class="cursor-info-badge" style="display:none;">
            <span>i</span>
      <button id="create-video" class="primary" type="button" hidden>Video erstellen</button>
    </div>
  </div>
</footer>

<input type="file" id="picker" accept="video/*,audio/*,.txt,.md,.pdf" multiple hidden>

<script>
const $ = id => document.getElementById(id);
const MOCK = new URLSearchParams(location.search).get('mock');
const state = {
  files: [],
  chunks: [],
  generating: false,
  uploading: false,
  pollingRecommendations: false,
  finalizing: false,
  applyingRecommendations: false,
  recommendationsStatus: 'complete',
  recognition: null,
  typingTimeout: null,
  orchestrateDebounce: null,
  canvasSaveTimeout: null,
  dismissed: {},
  activeGhostText: '',
  activeRecommendations: [],
  inflight: false,
  acceptedGhostTexts: new Set(),
  canvas: { title: 'Mein Startup Pitch', text: '', beats: {}, attached_videos: {} },
  canvasHydrated: false,
  hydratingCanvas: false,
  textRevision: 0,
  saveRevision: 0,
  orchestrationSequence: 0,
  assistSequences: { A1: 0, A2: 0, A3: 0 },
  orchestrationController: null,
  assistControllers: { A1: null, A2: null, A3: null },
  seenRequestIds: new Set(),
  lastAppliedRequestId: null,
  agentsAvailable: null,
  jobStatusTimeout: null,
};

const AGENT_META = {
  A1: { key: 'supervisor', role: 'Supervisor', beat: 'ASK' },
  A2: { key: 'director', role: 'Director', beat: 'HOOK' },
  A3: { key: 'strategist', role: 'Strategist', beat: 'TRACTION' },
};

// HTML escape helper
function escapeHtml(str) {
  return (str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function normalizeText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ').toLowerCase();
}

function setProgressValue(value) {
  const progress = Math.max(0, Math.min(100, Number(value) || 0));
  const line = $('progress-line');
  const popupProgress = $('job-status-progress');
  line.style.setProperty('--progress-value', `${progress}%`);
  line.setAttribute('aria-valuenow', String(progress));
  popupProgress.style.setProperty('--job-progress', `${progress}%`);
  popupProgress.setAttribute('aria-valuenow', String(progress));
}

function showJobStatus({ tone = 'active', title, detail, eta, progress, autoHide = 0 }) {
  clearTimeout(state.jobStatusTimeout);
  state.jobStatusTimeout = null;
  const card = $('job-status-card');
  card.dataset.tone = tone;
  $('job-status-title').textContent = title;
  $('job-status-detail').textContent = detail;
  $('job-status-eta').textContent = eta;
  setProgressValue(progress);
  card.hidden = false;
  if (autoHide) {
    state.jobStatusTimeout = setTimeout(() => {
      card.hidden = true;
      state.jobStatusTimeout = null;
    }, autoHide);
  }
}

function hideJobStatus() {
  clearTimeout(state.jobStatusTimeout);
  state.jobStatusTimeout = null;
  $('job-status-card').hidden = true;
}

function renderJobStatus(data) {
  const phase = String(data.phase || 'empty').toLowerCase();
  const reportedStatus = String(data.job_status || '').toLowerCase();

  if (phase === 'error') {
    showJobStatus({
      tone: 'error',
      title: 'Videoerstellung fehlgeschlagen',
      detail: 'Der Auftrag wurde gestoppt. Die genaue Ursache steht im Arbeitsbereich.',
      eta: 'Gestoppt',
      progress: 100,
    });
    return;
  }

  if (phase === 'working') {
    const status = ['queued', 'running', 'finalizing'].includes(reportedStatus)
      ? reportedStatus
      : (data.selection_complete ? 'finalizing' : 'running');
    const presentation = {
      queued: {
        tone: 'waiting',
        title: 'Videoauftrag angenommen',
        detail: 'Der Upload ist abgeschlossen und wartet auf die Verarbeitung.',
        eta: 'ca. 6–10 Min.',
        progress: 12,
      },
      running: {
        tone: 'active',
        title: 'Video wird erstellt',
        detail: 'Material wird analysiert, geschnitten und als Varianten gerendert.',
        eta: 'ca. 4–8 Min.',
        progress: 58,
      },
      finalizing: {
        tone: 'active',
        title: 'Finales Video wird gerendert',
        detail: 'Die ausgewählten Varianten werden zu einem Video zusammengesetzt.',
  const text = normalizeText($('prompt').value);
  const accepted = state.acceptedGhostTexts;
  const seen = new Set();
  return raw
    .map(item => {
      const agent = String(item?.agent || item?.agent_id || '').toUpperCase();
      const meta = AGENT_META[agent];
      if (!meta) return null;
      return {
        agent,
        role: item.role || meta.role,
        beat: item.beat || meta.beat,
        anchor_text: String(item.anchor_text || ''),
        message: String(item.message || item.missing_item || ''),
        ghost_text: String(item.ghost_text || ''),
      };
    })
    .filter(Boolean)
    .filter(item => {
      const ghost = normalizeText(item.ghost_text);
      if (ghost && (accepted.has(ghost) || text.includes(ghost))) item.ghost_text = '';
      const fingerprint = recommendationFingerprint(item);
      if (!item.message && !item.ghost_text) return false;
      if (seen.has(fingerprint)) return false;
      seen.add(fingerprint);
      return true;
    });
}

function mergeAgentRecommendations(items, replace = false) {
  const previous = new Map(state.activeRecommendations.map(item => [item.agent, item]));
  const next = replace ? new Map() : new Map(state.activeRecommendations.map(item => [item.agent, item]));
  items.forEach(item => {
    const old = previous.get(item.agent);
    if (!old || recommendationFingerprint(old) !== recommendationFingerprint(item)) {
      const key = AGENT_META[item.agent]?.key;
      if (key) delete state.dismissed[key];
    }
    next.set(item.agent, item);
  });
  state.activeRecommendations = [...next.values()];
}

function setAgentAvailability(available, message = '') {
  state.agentsAvailable = available;
  const notice = $('agent-status-message');
  notice.hidden = available !== false;
  if (available === false && message) notice.textContent = message;
  if (available === false) {
    state.activeGhostText = '';
    state.activeRecommendations = [];
    updateGhostOverlay();
    ['director', 'strategist', 'supervisor'].forEach(key => {
      const status = $(`status-${key}`);
      if (status) status.textContent = 'nicht verfügbar';
      const badge = $(`info-badge-${key}`);
      if (badge) badge.style.display = 'none';
    });
  }
}

async function loadAgentConfig() {
  if (MOCK) return;
  try {
    const response = await fetch('/api/devin/config');
    if (!response.ok) throw new Error();
    const data = await response.json();
    const configured = data.devin_configured ?? data.configured ?? data.available ?? false;
    setAgentAvailability(Boolean(configured), 'Devin ist nicht konfiguriert. Schreiben und manuelle Variantenauswahl bleiben verfügbar.');
  } catch (_) {
    setAgentAvailability(false, 'KI-Agenten sind gerade nicht erreichbar. Schreiben und manuelle Variantenauswahl bleiben verfügbar.');
  }
}

// Autosize textarea
function autosize(el) {
  el.style.height = 'auto';
  const minH = el.id === 'prompt' ? 220 : 280;
  const newH = Math.max(minH, el.scrollHeight);
  el.style.height = `${newH}px`;
    badgeDirector.style.display = 'none';
    if (sDirector) sDirector.textContent = idleAgentStatus();
  }

  // 2. Strategist Cursor (Anchored at Middle / Traction / KPIs)
  const posStrat = getWordCoordinates(anchoredOffset(text, recStrat, stratChar));
  cStrategist.style.transform = `translate(${posStrat.left}px, ${posStrat.top}px)`;

  if (recStrat && !state.dismissed['strategist'] && (recStrat.message || recStrat.missing_item)) {
    $('advice-text-strategist').textContent = recStrat.message || recStrat.missing_item;
    badgeStrategist.style.display = 'inline-flex';
    if (sStrategist) sStrategist.textContent = 'KPIs analysiert';
  } else {
    badgeStrategist.style.display = 'none';
    if (sStrategist) sStrategist.textContent = idleAgentStatus();
  }

  // 3. Supervisor Cursor (Anchored at End of Text / CTA)
  const posSuper = getWordCoordinates(anchoredOffset(text, recSuper, text.length));
  cSupervisor.style.transform = `translate(${posSuper.left}px, ${posSuper.top}px)`;

  if (recSuper && !state.dismissed['supervisor'] && (recSuper.message || recSuper.missing_item)) {
    $('advice-text-supervisor').textContent = recSuper.message || recSuper.missing_item;
    badgeSupervisor.style.display = 'inline-flex';
    if (sSupervisor) sSupervisor.textContent = 'Länge & CTA analysiert';
  } else {
    badgeSupervisor.style.display = 'none';
    if (sSupervisor) sSupervisor.textContent = idleAgentStatus();
  }
}

function updateComposer(immediate = false) {
  autosize($('prompt'));
  const text = $('prompt').value.trim();
  $('generate').disabled = text.length < 10 || state.generating;
  $('create-video').hidden = $('script-result').hidden || state.uploading;

  if (!immediate) {
    state.orchestrationController?.abort();
    state.orchestrationController = null;
    Object.keys(state.assistControllers).forEach(agentId => {
      state.assistControllers[agentId]?.abort();
      state.assistControllers[agentId] = null;
    });
  }

  if (text.length < 12) {
    state.orchestrationSequence += 1;
    state.activeRecommendations = [];
    state.activeGhostText = '';
  }

  // While actively typing: hide badges and ghost text to prevent flickering / distracting jumps
  if (!immediate) {
    updateGhostOverlay(true);
    const badgeDir = $('info-badge-director');
    const badgeStrat = $('info-badge-strategist');
    const badgeSuper = $('info-badge-supervisor');
    if (badgeDir) badgeDir.style.display = 'none';
    if (badgeStrat) badgeStrat.style.display = 'none';
    if (badgeSuper) badgeSuper.style.display = 'none';
  }

  // Deliberate pause before computing suggestions so text doesn't constantly change
  clearTimeout(state.typingTimeout);
  if (immediate) {
    renderAgentRecommendations();
  } else {
    state.typingTimeout = setTimeout(renderAgentRecommendations, 300);
  }

  // 550ms deliberate debounce before asking LLM for new pitch ideas
  clearTimeout(state.orchestrateDebounce);
  if (text.length >= 12 && state.agentsAvailable !== false) {
    state.orchestrateDebounce = setTimeout(triggerAgenticOrchestration, 550);
  }
}

async function triggerAgenticOrchestration() {
  const promptElement = $('prompt');
  const prompt = promptElement.value.trim();
  if (prompt.length < 12 || state.agentsAvailable === false) return;
  const sequence = ++state.orchestrationSequence;
  const revision = state.textRevision;
  const requestId = clientRequestId('orchestrate');
  state.orchestrationController?.abort();
  const controller = new AbortController();
  state.orchestrationController = controller;
  const cursorOffset = typeof promptElement.selectionStart === 'number'
    ? promptElement.selectionStart
    : promptElement.value.length;
  state.inflight = true;
  renderAgentRecommendations();

  try {
    const res = await fetch('/api/devin/orchestrate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({
        text: prompt,
        cursor_offset: cursorOffset,
        accepted_ghost_texts: [...state.acceptedGhostTexts],
        request_id: requestId,
      }),
    });
    if (!res.ok) {
      if ([401, 403, 429, 503].includes(res.status)) {
        setAgentAvailability(false, 'KI-Agenten sind gerade nicht verfügbar. Der Canvas und die manuelle Auswahl funktionieren weiter.');
      }
      return;
    }
    const data = await res.json();
    const responseId = String(data.request_id || requestId);
    const stale = sequence !== state.orchestrationSequence
      || revision !== state.textRevision
      || $('prompt').value.trim() !== prompt
      || state.seenRequestIds.has(responseId);
    if (stale) return;
    state.seenRequestIds.add(responseId);
    state.lastAppliedRequestId = responseId;
    mergeAgentRecommendations(normalizeAgentRecommendations(data), true);
    setAgentAvailability(true);
  } catch (error) {
    if (error?.name === 'AbortError') return;
    if (sequence === state.orchestrationSequence) {
      setAgentAvailability(false, 'KI-Agenten sind gerade nicht erreichbar. Der Canvas und die manuelle Auswahl funktionieren weiter.');
    }
  } finally {
    if (state.orchestrationController === controller) state.orchestrationController = null;
    if (sequence === state.orchestrationSequence) {
      state.inflight = false;
      renderAgentRecommendations();
    }
  }
}

async function requestAgentAssist(agentId) {
  const meta = AGENT_META[agentId];
  const promptElement = $('prompt');
  const text = promptElement.value.trim();
  if (!meta || text.length < 5 || state.agentsAvailable === false) return;
  const sequence = ++state.assistSequences[agentId];
  const revision = state.textRevision;
  const requestId = clientRequestId(`assist-${agentId.toLowerCase()}`);
  state.assistControllers[agentId]?.abort();
  const controller = new AbortController();
  state.assistControllers[agentId] = controller;
  const current = state.activeRecommendations.find(item => item.agent === agentId);
  state.inflight = true;
  renderAgentRecommendations();
  try {
    const response = await fetch('/api/canvas/assist', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({
        text,
        cursor_offset: typeof promptElement.selectionStart === 'number' ? promptElement.selectionStart : promptElement.value.length,
        accepted_ghost_texts: [...state.acceptedGhostTexts],
        agent_id: agentId,
        beat: current?.beat || meta.beat,
        request_id: requestId,
      }),
    });
    if (!response.ok) {
      if ([401, 403, 429, 503].includes(response.status)) {
        setAgentAvailability(false, 'Der Agent ist gerade nicht verfügbar. Du kannst ohne ihn weiterschreiben.');
      }
      return;
    }
    const data = await response.json();
    const responseId = String(data.request_id || requestId);
    const stale = sequence !== state.assistSequences[agentId]
      || revision !== state.textRevision
      || $('prompt').value.trim() !== text
      || state.seenRequestIds.has(responseId);
    if (stale) return;
    state.seenRequestIds.add(responseId);
    mergeAgentRecommendations(normalizeAgentRecommendations(data));
    setAgentAvailability(true);
  } catch (error) {
    if (error?.name === 'AbortError') return;
    if (sequence === state.assistSequences[agentId]) {
      setAgentAvailability(false, 'Der Agent ist gerade nicht erreichbar. Du kannst ohne ihn weiterschreiben.');
    }
  } finally {
    if (state.assistControllers[agentId] === controller) {
      state.assistControllers[agentId] = null;
    }
    if (sequence === state.assistSequences[agentId]) {
      state.inflight = false;
      renderAgentRecommendations();
    }
  }
}

function renderAttachments() {
  $('attachments').innerHTML = '';
  state.files.forEach((file, index) => {
    const item = document.createElement('span');
    item.className = 'attachment';
    item.append(document.createTextNode(file.name));
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.setAttribute('aria-label', `${file.name} entfernen`);
    remove.textContent = '×';
    remove.onclick = () => {
      state.files.splice(index, 1);
      renderAttachments();
      updateComposer(true);
    };
    item.append(remove);
    $('attachments').append(item);
  });
  if (state.files.length) {
    $('create-video').hidden = false;
  }
}

function selectFiles(files) {
  const incoming = [...files];
  if (!incoming.length) return;
  state.files.push(...incoming);
  renderAttachments();
}

async function generateScript() {
  const prompt = $('prompt').value.trim();
  if (prompt.length < 10 || state.generating) return;
  state.generating = true;
  $('compose-error').hidden = true;
  $('script-result').hidden = false;
  $('script-output').value = '';
  $('generator-source').textContent = 'wird geschrieben …';
  updateComposer(true);
  $('script-result').scrollIntoView({ behavior: 'smooth', block: 'start' });

  try {
    const response = await fetch('/api/script', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ prompt }),
    });
    if (!response.ok || !response.body) throw new Error('Das Skript konnte nicht erzeugt werden.');
    const source = response.headers.get('X-Palantum-Generator');
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      $('script-output').value += decoder.decode(value, { stream: true });
      autosize($('script-output'));
    }
    $('generator-source').textContent = source === 'devin' ? 'mit Devin erstellt' : 'lokaler Entwurf';
  } catch (error) {
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
    $('script-result').hidden = true;
  } finally {
    state.generating = false;
    updateComposer(true);
  }
}

async function uploadVideos(files, brief) {
  const videos = files.filter(f => f.type.startsWith('video/') || /\.(mp4|mov|webm|m4v)$/i.test(f.name));
  if (!videos.length) {
    $('compose-error').textContent = 'Für die Videoerstellung wird mindestens eine Videodatei benötigt.';
    $('compose-error').hidden = false;
    return;
  }
  clearTimeout(state.canvasSaveTimeout);
  if (state.canvasHydrated) await saveCanvas(++state.saveRevision);
  state.uploading = true;
  renderChunkReview(state.chunks, true);
  showJobStatus({
    tone: 'waiting',
    title: 'Finaler Render gestartet',
    detail: 'Die Auswahl wird für den finalen Videoschnitt vorbereitet.',
    eta: 'ca. 1–3 Min.',
    progress: 82,
  });
  try {
    const response = await fetch('/api/finalize', { method: 'POST' });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}));
      throw new Error(payload.detail || 'Das finale Video konnte nicht gestartet werden.');
    }
    state.uploading = true;
    $('chunk-review').hidden = true;
    $('progress').hidden = false;
    $('progress-copy').textContent = 'Deine Auswahl wird zusammengesetzt …';
    poll();
  } catch (error) {
    state.finalizing = false;
    renderChunkReview(state.chunks);
    showJobStatus({
      tone: 'error',
      title: 'Finaler Render fehlgeschlagen',
      detail: 'Der Auftrag konnte nicht gestartet werden.',
      eta: 'Gestoppt',
      progress: 100,
    });
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

function applyServerState(data) {
  hydrateCanvas(data.canvas || state.canvas);
  renderBeats(data.coverage?.beats || []);
  renderJobStatus(data);
  if (data.phase==='error') {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    $('progress').hidden = true;
    $('output').hidden = true;
    $('toolbar').hidden = false;
    $('compose-error').textContent = data.error || 'Die Videoverarbeitung ist fehlgeschlagen.';
    $('compose-error').hidden = false;
    return true;
  }
  if (data.phase === 'review') {
    state.uploading = false;
    state.recommendationsStatus = data.recommendations_status || 'complete';
    state.pollingRecommendations = data.recommendations_status === 'pending';
    state.finalizing = false;
    $('progress').hidden = true;
    $('output').hidden = true;
    $('chunk-review').hidden = false;
    $('toolbar').hidden = false;
    renderChunkReview(data.chunks || [], data.selection_complete ?? null);
    return !state.pollingRecommendations;
  }
  if (data.phase === 'done' && data.video_url) {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    $('progress').hidden = true;
    $('chunk-review').hidden = true;
    $('output').hidden = false;
    $('toolbar').hidden = true;
    $('player').src = data.video_url;
    $('export-video').href = data.video_url;
    $('export-folder').href = data.export_url || '#';
    $('export-fcpxml').href = data.fcpxml_url || data.export_url || '#';
    $('export-davinci').href = data.davinci_url || data.resolve_url || data.export_url || '#';
    return true;
  }
  if (data.phase === 'working') {
    state.uploading = true;
    state.pollingRecommendations = false;
    $('progress').hidden = false;
    $('chunk-review').hidden = true;
    $('output').hidden = true;
    $('toolbar').hidden = false;
    const score = Math.round((data.coverage?.score || 0) * 100);
    $('progress-copy').textContent = data.selection_complete
      ? 'Deine Auswahl wird zusammengesetzt …'
      : score
        ? `Chunks werden parallel bearbeitet · ${score}% Abdeckung`
        : 'Material wird analysiert …';
    return false;
  }
  state.uploading = false;
  state.pollingRecommendations = false;
  $('progress').hidden = true;
  $('chunk-review').hidden = true;
  $('output').hidden = true;
  $('toolbar').hidden = false;
  return true;
}

async function poll() {
  if (MOCK) return;
  try {
    const response = await fetch('/api/state');
    if (!response.ok) throw new Error();
    const done = applyServerState(await response.json());
    if (done) return;
  } catch (_) {}
  if (state.uploading || state.pollingRecommendations) setTimeout(poll, 1500);
}

async function loadInitialState() {
  if (MOCK) {
    const response = await fetch(`mock_state_${MOCK}.json`);
    const data = await response.json();
    applyServerState(data);
    return;
  }
  try {
    const response = await fetch('/api/state');
    if (!response.ok) throw new Error();
    const data = await response.json();
    const done = applyServerState(data);
    if (!done && (state.uploading || state.pollingRecommendations)) setTimeout(poll, 1500);
  } catch (_) {
    hydrateCanvas(state.canvas);
    $('compose-error').textContent = 'Der Projektstatus konnte nicht geladen werden. Der Canvas bleibt nutzbar.';
    $('compose-error').hidden = false;
  }
}

function startDictation() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    $('compose-error').textContent = 'Diktat wird von diesem Browser nicht unterstützt.';
    $('compose-error').hidden = false;
    return;
  }
  if (state.recognition) {
    state.recognition.stop();
    return;
  }
  const recognition = new SpeechRecognition();
  recognition.lang = 'de-DE';
  recognition.interimResults = true;

