// HTML escape helper
function escapeHtml(str) {
  return (str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function normalizeText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ').toLowerCase();
}

function setProgressValue(value) {
  const progress = Math.max(0, Math.min(100, Number(value) || 0));
  const line = $('progress-line');
  const popupProgress = $('job-status-progress');
  line.style.setProperty('--progress-value', `${progress}%`);
  line.setAttribute('aria-valuenow', String(progress));
  popupProgress.style.setProperty('--job-progress', `${progress}%`);
  popupProgress.setAttribute('aria-valuenow', String(progress));
}

function showJobStatus({ tone = 'active', title, detail, eta, progress, autoHide = 0 }) {
  clearTimeout(state.jobStatusTimeout);
  state.jobStatusTimeout = null;
  const card = $('job-status-card');
  card.dataset.tone = tone;
  $('job-status-title').textContent = title;
  $('job-status-detail').textContent = detail;
  $('job-status-eta').textContent = eta;
  setProgressValue(progress);
  card.hidden = false;
  if (autoHide) {
    state.jobStatusTimeout = setTimeout(() => {
      card.hidden = true;
      state.jobStatusTimeout = null;
    }, autoHide);
  }
}

function hideJobStatus() {
  clearTimeout(state.jobStatusTimeout);
  state.jobStatusTimeout = null;
  $('job-status-card').hidden = true;
}

function renderJobStatus(data) {
  const phase = String(data.phase || 'empty').toLowerCase();
  const reportedStatus = String(data.job_status || '').toLowerCase();

  if (phase === 'error') {
    showJobStatus({
      tone: 'error',
      title: 'Videoerstellung fehlgeschlagen',
      detail: 'Der Auftrag wurde gestoppt. Die genaue Ursache steht im Arbeitsbereich.',
      eta: 'Gestoppt',
      progress: 100,
    });
    return;
  }

  if (phase === 'working') {
    const status = ['queued', 'running', 'finalizing'].includes(reportedStatus)
      ? reportedStatus
      : (data.selection_complete ? 'finalizing' : 'running');
    const presentation = {
      queued: {
        tone: 'waiting',
        title: 'Videoauftrag angenommen',
        detail: 'Der Upload ist abgeschlossen und wartet auf die Verarbeitung.',
        eta: 'ca. 6–10 Min.',
        progress: 12,
      },
      running: {
        tone: 'active',
        title: 'Video wird erstellt',
        detail: 'Material wird analysiert, geschnitten und als Varianten gerendert.',
        eta: 'ca. 4–8 Min.',
        progress: 58,
      },
      finalizing: {
        tone: 'active',
        title: 'Finales Video wird gerendert',
        detail: 'Die ausgewählten Varianten werden zu einem Video zusammengesetzt.',
  const text = normalizeText($('prompt').value);
  const accepted = state.acceptedGhostTexts;
  const seen = new Set();
  return raw
    .map(item => {
      const agent = String(item?.agent || item?.agent_id || '').toUpperCase();
      const meta = AGENT_META[agent];
      if (!meta) return null;
      return {
        agent,
        role: item.role || meta.role,
        beat: item.beat || meta.beat,
        anchor_text: String(item.anchor_text || ''),
        message: String(item.message || item.missing_item || ''),
        ghost_text: String(item.ghost_text || ''),
      };
    })
    .filter(Boolean)
    .filter(item => {
      const ghost = normalizeText(item.ghost_text);
      if (ghost && (accepted.has(ghost) || text.includes(ghost))) item.ghost_text = '';
      const fingerprint = recommendationFingerprint(item);
      if (!item.message && !item.ghost_text) return false;
      if (seen.has(fingerprint)) return false;
      seen.add(fingerprint);
      return true;
    });
}

function mergeAgentRecommendations(items, replace = false) {
  const previous = new Map(state.activeRecommendations.map(item => [item.agent, item]));
  const next = replace ? new Map() : new Map(state.activeRecommendations.map(item => [item.agent, item]));
  items.forEach(item => {
    const old = previous.get(item.agent);
    if (!old || recommendationFingerprint(old) !== recommendationFingerprint(item)) {
      const key = AGENT_META[item.agent]?.key;
      if (key) delete state.dismissed[key];
    }
    next.set(item.agent, item);
  });
  state.activeRecommendations = [...next.values()];
}

function setAgentAvailability(available, message = '') {
  state.agentsAvailable = available;
  const notice = $('agent-status-message');
  notice.hidden = available !== false;
  if (available === false && message) notice.textContent = message;
  if (available === false) {
    state.activeGhostText = '';
    state.activeRecommendations = [];
    updateGhostOverlay();
    ['director', 'strategist', 'supervisor'].forEach(key => {
      const status = $(`status-${key}`);
      if (status) status.textContent = 'nicht verfügbar';
      const badge = $(`info-badge-${key}`);
      if (badge) badge.style.display = 'none';
    });
  }
}

async function loadAgentConfig() {
  if (MOCK) return;
  try {
    const response = await fetch('/api/devin/config');
    if (!response.ok) throw new Error();
    const data = await response.json();
    const configured = data.devin_configured ?? data.configured ?? data.available ?? false;
    setAgentAvailability(Boolean(configured), 'Devin ist nicht konfiguriert. Schreiben und manuelle Variantenauswahl bleiben verfügbar.');
  } catch (_) {
    setAgentAvailability(false, 'KI-Agenten sind gerade nicht erreichbar. Schreiben und manuelle Variantenauswahl bleiben verfügbar.');
  }
}

// Autosize textarea
function autosize(el) {
  el.style.height = 'auto';
  const minH = el.id === 'prompt' ? 220 : 280;
  const newH = Math.max(minH, el.scrollHeight);
  el.style.height = `${newH}px`;
    badgeDirector.style.display = 'none';
    if (sDirector) sDirector.textContent = idleAgentStatus();
  }

  // 2. Strategist Cursor (Anchored at Middle / Traction / KPIs)
  const posStrat = getWordCoordinates(anchoredOffset(text, recStrat, stratChar));
  cStrategist.style.transform = `translate(${posStrat.left}px, ${posStrat.top}px)`;

  if (recStrat && !state.dismissed['strategist'] && (recStrat.message || recStrat.missing_item)) {
    $('advice-text-strategist').textContent = recStrat.message || recStrat.missing_item;
    badgeStrategist.style.display = 'inline-flex';
    if (sStrategist) sStrategist.textContent = 'KPIs analysiert';
  } else {
    badgeStrategist.style.display = 'none';
    if (sStrategist) sStrategist.textContent = idleAgentStatus();
  }

  // 3. Supervisor Cursor (Anchored at End of Text / CTA)
  const posSuper = getWordCoordinates(anchoredOffset(text, recSuper, text.length));
  cSupervisor.style.transform = `translate(${posSuper.left}px, ${posSuper.top}px)`;

  if (recSuper && !state.dismissed['supervisor'] && (recSuper.message || recSuper.missing_item)) {
    $('advice-text-supervisor').textContent = recSuper.message || recSuper.missing_item;
    badgeSupervisor.style.display = 'inline-flex';
    if (sSupervisor) sSupervisor.textContent = 'Länge & CTA analysiert';
  } else {
    badgeSupervisor.style.display = 'none';
    if (sSupervisor) sSupervisor.textContent = idleAgentStatus();
  }
}

function updateComposer(immediate = false) {
  autosize($('prompt'));
  const text = $('prompt').value.trim();
  $('generate').disabled = text.length < 10 || state.generating;
  $('create-video').hidden = $('script-result').hidden || state.uploading;

  if (!immediate) {
    state.orchestrationController?.abort();
    state.orchestrationController = null;
    Object.keys(state.assistControllers).forEach(agentId => {
      state.assistControllers[agentId]?.abort();
      state.assistControllers[agentId] = null;
    });
  }

  if (text.length < 12) {
    state.orchestrationSequence += 1;
    state.activeRecommendations = [];
    state.activeGhostText = '';
  }

  // While actively typing: hide badges and ghost text to prevent flickering / distracting jumps
  if (!immediate) {
    updateGhostOverlay(true);
    const badgeDir = $('info-badge-director');
    const badgeStrat = $('info-badge-strategist');
    const badgeSuper = $('info-badge-supervisor');
    if (badgeDir) badgeDir.style.display = 'none';
    if (badgeStrat) badgeStrat.style.display = 'none';
    if (badgeSuper) badgeSuper.style.display = 'none';
  }

  // Deliberate pause before computing suggestions so text doesn't constantly change
  clearTimeout(state.typingTimeout);
  if (immediate) {
    renderAgentRecommendations();
  } else {
    state.typingTimeout = setTimeout(renderAgentRecommendations, 300);
  }

  // 550ms deliberate debounce before asking LLM for new pitch ideas
  clearTimeout(state.orchestrateDebounce);
  if (text.length >= 12 && state.agentsAvailable !== false) {
    state.orchestrateDebounce = setTimeout(triggerAgenticOrchestration, 550);
  }
}

async function triggerAgenticOrchestration() {
  const promptElement = $('prompt');
  const prompt = promptElement.value.trim();
  if (prompt.length < 12 || state.agentsAvailable === false) return;
  const sequence = ++state.orchestrationSequence;
  const revision = state.textRevision;
  const requestId = clientRequestId('orchestrate');
  state.orchestrationController?.abort();
  const controller = new AbortController();
  state.orchestrationController = controller;
  const cursorOffset = typeof promptElement.selectionStart === 'number'
    ? promptElement.selectionStart
    : promptElement.value.length;
  state.inflight = true;
  renderAgentRecommendations();

  try {
    const res = await fetch('/api/devin/orchestrate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({
        text: prompt,
        cursor_offset: cursorOffset,
        accepted_ghost_texts: [...state.acceptedGhostTexts],
        request_id: requestId,
      }),
    });
    if (!res.ok) {
      if ([401, 403, 429, 503].includes(res.status)) {
        setAgentAvailability(false, 'KI-Agenten sind gerade nicht verfügbar. Der Canvas und die manuelle Auswahl funktionieren weiter.');
      }
      return;
    }
    const data = await res.json();
    const responseId = String(data.request_id || requestId);
    const stale = sequence !== state.orchestrationSequence
      || revision !== state.textRevision
      || $('prompt').value.trim() !== prompt
      || state.seenRequestIds.has(responseId);
    if (stale) return;
    state.seenRequestIds.add(responseId);
    state.lastAppliedRequestId = responseId;
    mergeAgentRecommendations(normalizeAgentRecommendations(data), true);
    setAgentAvailability(true);
  } catch (error) {
    if (error?.name === 'AbortError') return;
    if (sequence === state.orchestrationSequence) {
      setAgentAvailability(false, 'KI-Agenten sind gerade nicht erreichbar. Der Canvas und die manuelle Auswahl funktionieren weiter.');
    }
  } finally {
    if (state.orchestrationController === controller) state.orchestrationController = null;
    if (sequence === state.orchestrationSequence) {
      state.inflight = false;
      renderAgentRecommendations();
    }
  }
}

async function requestAgentAssist(agentId) {
  const meta = AGENT_META[agentId];
  const promptElement = $('prompt');
  const text = promptElement.value.trim();
  if (!meta || text.length < 5 || state.agentsAvailable === false) return;
  const sequence = ++state.assistSequences[agentId];
  const revision = state.textRevision;
  const requestId = clientRequestId(`assist-${agentId.toLowerCase()}`);
  state.assistControllers[agentId]?.abort();
  const controller = new AbortController();
  state.assistControllers[agentId] = controller;
  const current = state.activeRecommendations.find(item => item.agent === agentId);
  state.inflight = true;
  renderAgentRecommendations();
  try {
    const response = await fetch('/api/canvas/assist', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({
        text,
        cursor_offset: typeof promptElement.selectionStart === 'number' ? promptElement.selectionStart : promptElement.value.length,
        accepted_ghost_texts: [...state.acceptedGhostTexts],
        agent_id: agentId,
        beat: current?.beat || meta.beat,
        request_id: requestId,
      }),
    });
    if (!response.ok) {
      if ([401, 403, 429, 503].includes(response.status)) {
        setAgentAvailability(false, 'Der Agent ist gerade nicht verfügbar. Du kannst ohne ihn weiterschreiben.');
      }
      return;
    }
    const data = await response.json();
    const responseId = String(data.request_id || requestId);
    const stale = sequence !== state.assistSequences[agentId]
      || revision !== state.textRevision
      || $('prompt').value.trim() !== text
      || state.seenRequestIds.has(responseId);
    if (stale) return;
    state.seenRequestIds.add(responseId);
    mergeAgentRecommendations(normalizeAgentRecommendations(data));
    setAgentAvailability(true);
  } catch (error) {
    if (error?.name === 'AbortError') return;
    if (sequence === state.assistSequences[agentId]) {
      setAgentAvailability(false, 'Der Agent ist gerade nicht erreichbar. Du kannst ohne ihn weiterschreiben.');
    }
  } finally {
    if (state.assistControllers[agentId] === controller) {
      state.assistControllers[agentId] = null;
    }
    if (sequence === state.assistSequences[agentId]) {
      state.inflight = false;
      renderAgentRecommendations();
    }
  }
}

function renderAttachments() {
  $('attachments').innerHTML = '';
  state.files.forEach((file, index) => {
    const item = document.createElement('span');
    item.className = 'attachment';
    item.append(document.createTextNode(file.name));
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.setAttribute('aria-label', `${file.name} entfernen`);
    remove.textContent = '×';
    remove.onclick = () => {
