    cSupervisor.style.transform = 'translate(0px, 0px)';
    badgeDirector.style.display = 'none';
    badgeStrategist.style.display = 'none';
    badgeSupervisor.style.display = 'none';
    state.activeGhostText = '';
    updateGhostOverlay();
    const statusText = idleAgentStatus();
    if (sDirector) sDirector.textContent = statusText;
    if (sStrategist) sStrategist.textContent = statusText;
