function hideJobStatus() {
  clearTimeout(state.jobStatusTimeout);
  state.jobStatusTimeout = null;
  $('job-status-card').hidden = true;
}

function renderJobStatus(data) {
  const phase = String(data.phase || 'empty').toLowerCase();
  const reportedStatus = String(data.job_status || '').toLowerCase();

  if (phase === 'error') {
    showJobStatus({
      tone: 'error',
      title: 'Videoerstellung fehlgeschlagen',
      detail: 'Der Auftrag wurde gestoppt. Die genaue Ursache steht im Arbeitsbereich.',
      eta: 'Gestoppt',
      progress: 100,
    });
    return;
  }

  if (phase === 'working') {
    const status = ['queued', 'running', 'finalizing'].includes(reportedStatus)
      ? reportedStatus
      : (data.selection_complete ? 'finalizing' : 'running');
    const presentation = {
      queued: {
        tone: 'waiting',
        title: 'Videoauftrag angenommen',
        detail: 'Der Upload ist abgeschlossen und wartet auf die Verarbeitung.',
        eta: 'ca. 6–10 Min.',
        progress: 12,
      },
      running: {
        tone: 'active',
        title: 'Video wird erstellt',
        detail: 'Material wird analysiert, geschnitten und als Varianten gerendert.',
        eta: 'ca. 4–8 Min.',
        progress: 58,
      },
      finalizing: {
        tone: 'active',
        title: 'Finales Video wird gerendert',
        detail: 'Die ausgewählten Varianten werden zu einem Video zusammengesetzt.',
        eta: 'ca. 1–3 Min.',
        progress: 88,
      },
    }[status];
    showJobStatus(presentation);
    return;
  }

  if (phase === 'review') {
    if (data.recommendations_status === 'pending') {
      showJobStatus({
        tone: 'active',
        title: 'Varianten sind gerendert',
        detail: 'Die KI-Empfehlungen für die Auswahl werden noch geprüft.',
        eta: 'ca. 1–2 Min.',
        progress: 94,
      });
    } else {
      showJobStatus({
        tone: 'success',
        title: 'Varianten sind bereit',
        detail: 'Du kannst jetzt die Schnittvarianten vergleichen und auswählen.',
        eta: 'Abgeschlossen',
        progress: 100,
        autoHide: 7000,
      });
    }
    return;
  }

  if (phase === 'done' && data.video_url) {
    showJobStatus({
      tone: 'success',
      title: 'Video ist fertig',
      detail: 'Das finale Video kann jetzt angesehen oder exportiert werden.',
      eta: 'Abgeschlossen',
      progress: 100,
      autoHide: 10000,
    });
    return;
  }

  hideJobStatus();
  setProgressValue(0);
}

function clientRequestId(prefix) {
  const random = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  return `${prefix}-${random}`;
}

function recommendationFingerprint(item) {
  return [item.agent, item.beat, item.anchor_text, item.message, item.ghost_text]
    .map(normalizeText)
    .join('|');
}

function normalizeAgentRecommendations(payload) {
  let raw = Array.isArray(payload?.agents) ? payload.agents : [];
  if (!raw.length && payload?.agents && typeof payload.agents === 'object') {
    raw = Object.entries(payload.agents).map(([agent, item]) => ({ agent, ...(item || {}) }));
  }
  if (!raw.length && Array.isArray(payload?.recommendations)) raw = payload.recommendations;
  if (!raw.length && payload?.agent) raw = [payload];

  const text = normalizeText($('prompt').value);
  const accepted = state.acceptedGhostTexts;
  const seen = new Set();
  return raw
    .map(item => {
      const agent = String(item?.agent || item?.agent_id || '').toUpperCase();
      const meta = AGENT_META[agent];
      if (!meta) return null;
      return {
        agent,
        role: item.role || meta.role,
        beat: item.beat || meta.beat,
        anchor_text: String(item.anchor_text || ''),
        message: String(item.message || item.missing_item || ''),
        ghost_text: String(item.ghost_text || ''),
      };
    })
    .filter(Boolean)
    .filter(item => {
      const ghost = normalizeText(item.ghost_text);
      if (ghost && (accepted.has(ghost) || text.includes(ghost))) item.ghost_text = '';
      const fingerprint = recommendationFingerprint(item);
      if (!item.message && !item.ghost_text) return false;
      if (seen.has(fingerprint)) return false;
      seen.add(fingerprint);
      return true;
    });
}

function mergeAgentRecommendations(items, replace = false) {
  const previous = new Map(state.activeRecommendations.map(item => [item.agent, item]));
  const next = replace ? new Map() : new Map(state.activeRecommendations.map(item => [item.agent, item]));
  items.forEach(item => {
    const old = previous.get(item.agent);
    if (!old || recommendationFingerprint(old) !== recommendationFingerprint(item)) {
  const text = prompt.value;
  const trimmed = text.trim();

  const cDirector = $('cursor-director');
  const cStrategist = $('cursor-strategist');
  const cSupervisor = $('cursor-supervisor');

  const badgeDirector = $('info-badge-director');
  const badgeStrategist = $('info-badge-strategist');
  const badgeSupervisor = $('info-badge-supervisor');

  const sDirector = $('status-director');
  const sStrategist = $('status-strategist');
  const sSupervisor = $('status-supervisor');

  updateMirrorDimensions();

  // If text is empty or too short, keep all 3 cursors stacked cleanly at start (0,0)
  if (!trimmed || trimmed.length < 5) {
    cDirector.style.transform = 'translate(0px, 0px)';
    cStrategist.style.transform = 'translate(0px, 0px)';
    cSupervisor.style.transform = 'translate(0px, 0px)';
    badgeDirector.style.display = 'none';
    badgeStrategist.style.display = 'none';
    badgeSupervisor.style.display = 'none';
    state.activeGhostText = '';
    updateGhostOverlay();
    const statusText = idleAgentStatus();
    if (sDirector) sDirector.textContent = statusText;
    if (sStrategist) sStrategist.textContent = statusText;
    if (sSupervisor) sSupervisor.textContent = statusText;
    return;
  }

  const sentences = text.split(/(?<=[.?!])\s+/).filter(Boolean);
  const recs = state.activeRecommendations || [];

  const recDir = recs.find(r => r.agent === 'A2' || (r.role && r.role.toLowerCase().includes('director')));
  const recStrat = recs.find(r => r.agent === 'A3' || (r.role && r.role.toLowerCase().includes('strateg')));
  const recSuper = recs.find(r => r.agent === 'A1' || (r.role && r.role.toLowerCase().includes('supervisor')));

  // Accurate structural sentence boundaries
  let firstSentenceEnd = text.length;
  if (sentences.length > 1) {
    firstSentenceEnd = text.indexOf(sentences[1]);
  } else if (text.indexOf('.') !== -1) {
    firstSentenceEnd = text.indexOf('.') + 1;
  }

  let stratChar = text.length;
  if (sentences.length > 2) {
    stratChar = text.indexOf(sentences[2]);
  }

  // Strictly bind ghost text to the responsible agent's cursor region
  let bestGhost = '';
  const caretPos = (document.activeElement === prompt && typeof prompt.selectionStart === 'number') ? prompt.selectionStart : text.length;

  if (caretPos <= firstSentenceEnd) {
    // Caret is at Hook (Director)
    if (recDir && recDir.ghost_text && !state.dismissed['director']) {
      bestGhost = recDir.ghost_text;
    } else if (sentences.length === 1 && recStrat && recStrat.ghost_text && !state.dismissed['strategist']) {
      bestGhost = recStrat.ghost_text;
    }
  } else if (caretPos <= stratChar || sentences.length <= 2) {
    // Caret is in Story / KPIs (Strategist)
    if (recStrat && recStrat.ghost_text && !state.dismissed['strategist']) {
      bestGhost = recStrat.ghost_text;
    } else if (recSuper && recSuper.ghost_text && !state.dismissed['supervisor']) {
      bestGhost = recSuper.ghost_text;
    }
  } else {
    // Caret is at End of text (Supervisor)
    if (recSuper && recSuper.ghost_text && !state.dismissed['supervisor']) {
      bestGhost = recSuper.ghost_text;
    } else if (recStrat && recStrat.ghost_text && !state.dismissed['strategist']) {
      bestGhost = recStrat.ghost_text;
    }
  }

  // De-duplicate against current text and already accepted ghost texts
  if (bestGhost) {
    const bgNorm = bestGhost.trim().toLowerCase();
    if (text.toLowerCase().includes(bgNorm) || state.acceptedGhostTexts.has(bgNorm)) {
      bestGhost = '';
    }
  }
  state.activeGhostText = bestGhost;
  updateGhostOverlay();

  // 1. Director Cursor (Anchored at Hook / Sentence 1 only if active or text exists)
  const posDir = getWordCoordinates(anchoredOffset(text, recDir, firstSentenceEnd));
  cDirector.style.transform = `translate(${posDir.left}px, ${posDir.top}px)`;

  if (recDir && !state.dismissed['director'] && (recDir.message || recDir.missing_item)) {
    $('advice-text-director').textContent = recDir.message || recDir.missing_item;
    badgeDirector.style.display = 'inline-flex';
    if (sDirector) sDirector.textContent = 'Hook analysiert';
  } else {
    badgeDirector.style.display = 'none';
    if (sDirector) sDirector.textContent = idleAgentStatus();
  }

  // 2. Strategist Cursor (Anchored at Middle / Traction / KPIs)
  const posStrat = getWordCoordinates(anchoredOffset(text, recStrat, stratChar));
  cStrategist.style.transform = `translate(${posStrat.left}px, ${posStrat.top}px)`;

  if (recStrat && !state.dismissed['strategist'] && (recStrat.message || recStrat.missing_item)) {
    $('advice-text-strategist').textContent = recStrat.message || recStrat.missing_item;
    badgeStrategist.style.display = 'inline-flex';
    if (sStrategist) sStrategist.textContent = 'KPIs analysiert';
  } else {
    badgeStrategist.style.display = 'none';
    if (sStrategist) sStrategist.textContent = idleAgentStatus();
    const data = await response.json().catch(() => ({}));
    const chunks = Array.isArray(data.chunks)
      ? data.chunks
      : state.chunks.map(chunk => {
          const recommendation = validChunkRecommendation(chunk);
          return recommendation ? { ...chunk, selected: recommendation.variant_id } : chunk;
        });
    state.applyingRecommendations = false;
    renderChunkReview(chunks, data.selection_complete ?? null);
  } catch (error) {
    state.applyingRecommendations = false;
    renderChunkReview(state.chunks);
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

async function finalizeVideo() {
  if ($('finalize').disabled) return;
  state.finalizing = true;
  renderChunkReview(state.chunks, true);
  showJobStatus({
    tone: 'waiting',
    title: 'Finaler Render gestartet',
    detail: 'Die Auswahl wird für den finalen Videoschnitt vorbereitet.',
    eta: 'ca. 1–3 Min.',
    progress: 82,
  });
  try {
    const response = await fetch('/api/finalize', { method: 'POST' });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}));
      throw new Error(payload.detail || 'Das finale Video konnte nicht gestartet werden.');
    }
    state.uploading = true;
    $('chunk-review').hidden = true;
    $('progress').hidden = false;
    $('progress-copy').textContent = 'Deine Auswahl wird zusammengesetzt …';
    poll();
  } catch (error) {
    state.finalizing = false;
    renderChunkReview(state.chunks);
    showJobStatus({
      tone: 'error',
      title: 'Finaler Render fehlgeschlagen',
      detail: 'Der Auftrag konnte nicht gestartet werden.',
      eta: 'Gestoppt',
      progress: 100,
    });
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

function applyServerState(data) {
  hydrateCanvas(data.canvas || state.canvas);
  renderBeats(data.coverage?.beats || []);
  renderJobStatus(data);
  if (data.phase==='error') {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    $('progress').hidden = true;
    $('output').hidden = true;
    $('toolbar').hidden = false;
    $('compose-error').textContent = data.error || 'Die Videoverarbeitung ist fehlgeschlagen.';
    $('compose-error').hidden = false;
    return true;
  }
  if (data.phase === 'review') {
    state.uploading = false;
    state.recommendationsStatus = data.recommendations_status || 'complete';
    state.pollingRecommendations = data.recommendations_status === 'pending';
    state.finalizing = false;
    $('progress').hidden = true;
    $('output').hidden = true;
    $('chunk-review').hidden = false;
    $('toolbar').hidden = false;
    renderChunkReview(data.chunks || [], data.selection_complete ?? null);
    return !state.pollingRecommendations;
  }
  if (data.phase === 'done' && data.video_url) {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    $('progress').hidden = true;
    $('chunk-review').hidden = true;
    $('output').hidden = false;
    $('toolbar').hidden = true;
    $('player').src = data.video_url;
    $('export-video').href = data.video_url;
    $('export-folder').href = data.export_url || '#';
    $('export-fcpxml').href = data.fcpxml_url || data.export_url || '#';
    $('export-davinci').href = data.davinci_url || data.resolve_url || data.export_url || '#';
    return true;
    variants = chunk.get("variants", [])
    return selected is not None and any(
        isinstance(variant, dict) and variant.get("id") == selected for variant in variants
    )


def _selection_complete(chunks: Any) -> bool:
    return isinstance(chunks, list) and bool(chunks) and all(
        _chunk_selection_is_valid(chunk) for chunk in chunks
    )


def _failure_message(error: Exception) -> str:
    missing = str(error).strip("'") if isinstance(error, KeyError) else ""
    if missing in {"OPENAI_API_KEY", "DEVIN_API_KEY", "DEVIN_PAT"}:
        return f"{missing} fehlt. Bitte den Schlüssel in der .env konfigurieren."
    detail = str(error).strip()
    return f"{type(error).__name__}: {detail}" if detail else type(error).__name__


def _sessions(edit_dir: Path) -> list[dict[str, Any]]:
    path = edit_dir / "sessions.json"
    raw: dict[str, Any] = {}
    if path.exists():
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                raw = loaded
        except (OSError, TypeError, ValueError):
            pass
    result = []
    for role, name in ROLE_NAMES.items():
        entries = [
            entry
            for key, entry in raw.items()
            if isinstance(entry, dict) and (key == role or entry.get("role") == role)
        ]
        priority = {"idle": 0, "done": 1, "failed": 2, "running": 3}
        entry = max(
            entries,
            key=lambda item: priority.get(str(item.get("status", "idle")), 0),
            default={},
        )
        result.append(
            {
                "role": name,
                "status": str(entry.get("status", "idle")),
                "url": entry.get("url"),
            }
        )
    return result


def _note_payload(note: dict[str, Any], resolved: bool = False) -> dict[str, Any]:
    shot = note.get("shot")
    if not isinstance(shot, dict):
        shot = {"line": "", "framing": "", "duration_s": 0, "delivery": ""}
    return {
        "beat": str(note.get("beat", "")),
        "impact": str(note.get("impact", "medium")),
        "resolved": resolved,
        "why": str(note.get("why", "")),
        "shot": {
            "line": str(shot.get("line", "")),
            "framing": str(shot.get("framing", "")),
            "duration_s": shot.get("duration_s", 0),
            "delivery": str(shot.get("delivery", "")),
        },
    }


def state_payload(videos_dir: Path) -> dict[str, Any]:
    edit_dir = videos_dir / "edit"
    state = load(edit_dir, _schema())
    job = _job(edit_dir)
    canvas = _load_canvas(edit_dir)
    sources = state.get("meta", {}).get("sources", [])
    has_sources = bool(sources) or any(
        next(videos_dir.glob(pattern), None) is not None for pattern in ("*.mp4", "*.mov")
    )
    final = edit_dir / "final.mp4"
    job_status = str(job.get("status", ""))
    with _MANIFEST_LOCK:
        chunk_manifest = _read_chunks(edit_dir)
    chunks = _chunk_payload(edit_dir, chunk_manifest)
    recommendations_status = str(
        chunk_manifest.get("recommendations_status", "complete")
    )
    if recommendations_status not in {"pending", "complete", "unavailable"}:
        recommendations_status = "complete"
    if job_status == "failed":
        phase = "error"
    elif job_status in {"queued", "running", "finalizing"}:
        phase = "working"
    elif job_status == "review":
        phase = "review"
    elif final.exists():
        phase = "done"
    elif not has_sources:
        phase = "empty"
    else:
        phase = "working"
    open_notes = [
        _note_payload(note)
        for note in state.get("director_notes", [])
        if isinstance(note, dict)
    ]
    resolved_notes = []
    for item in state.get("resolved_notes", []):
        if not isinstance(item, dict):
            continue
        nested = item.get("note")
        note = nested if isinstance(nested, dict) else item
        resolved_notes.append(_note_payload(note, resolved=True))
    beats = [
        {
            "id": str(beat["id"]),
            "status": str(beat["status"]),
            "reason": str(beat.get("reason", "")),
        }
        for beat in state.get("beats", [])
    ]
    selection_complete = _selection_complete(chunks)
    return {
        "phase": phase,
        "job_status": job_status or "idle",
        "coverage": {"score": state.get("coverage_score", 0.0), "beats": beats},
        "canvas": canvas,
        "notes": open_notes + resolved_notes,
        "sessions": [] if phase == "empty" else _sessions(edit_dir),
        "video_url": "/api/video" if final.exists() else None,
        "export_url": "/api/export" if final.exists() else None,
        "error": job.get("error") if phase == "error" else None,
        "chunks": chunks,
        "recommendations_status": recommendations_status,
        "selection_complete": selection_complete,
    }


def _process_upload(
    videos_dir: Path,
    sources: list[Path],
    brief: str | None,
    template_source: Path | None = None,
) -> None:
    with _PIPELINE_LOCK:
        edit_dir = videos_dir / "edit"
        _write_job(edit_dir, "running")
        try:
            analyze(edit_dir, sources, template_source, brief=brief)
            state = load(edit_dir, _schema())
            all_sources = [
                Path(str(value)).resolve() for value in state.get("meta", {}).get("sources", [])
            ]
            with _MANIFEST_LOCK:
                manifest = build_chunk_variants(edit_dir, all_sources, template_source)
            _write_job(edit_dir, "review")
        except Exception as error:
            _write_job(edit_dir, "failed", _failure_message(error))
        else:
            generation_id = str(manifest.get("generation_id", ""))
            if generation_id:
                try:
                    _RECOMMENDATION_EXECUTOR.submit(
                        _process_chunk_recommendations, videos_dir, generation_id
                    )
                except RuntimeError:
                    unavailable = {
                        str(chunk.get("id", "")): {
                            "status": "unavailable",
                            "variant_id": None,
                            "reason": "Die KI-Empfehlung ist derzeit nicht verfügbar.",
                        }
                        for chunk in manifest.get("chunks", [])
                        if isinstance(chunk, dict) and str(chunk.get("id", ""))
                    }
                    _apply_recommendation_batch(
                        edit_dir,
                        generation_id,
                        unavailable,
                        status="unavailable",
                    )


def _finalize_selection(videos_dir: Path) -> None:
    with _PIPELINE_LOCK:
        edit_dir = videos_dir / "edit"
        _write_job(edit_dir, "finalizing")
        try:
            with _MANIFEST_LOCK:
                finalize_chunk_variants(edit_dir)
            _write_job(edit_dir, "done")
        except Exception as error:
            _write_job(edit_dir, "failed", _failure_message(error))


def _raise_canvas_error(error: Exception) -> NoReturn:
    if isinstance(error, CanvasAgentUnavailableError):
        raise HTTPException(status_code=503, detail=str(error)) from error
    if isinstance(error, CanvasAgentResponseError):
        raise HTTPException(
            status_code=502, detail="Devin lieferte keine gültige Empfehlung."
        ) from error
    raise error


def _transcribe_with_whisper(path: Path, api_key: str) -> str:
    """Run the blocking Whisper SDK call outside the async request loop."""
    from openai import OpenAI

    with path.open("rb") as audio_handle:
        transcript = OpenAI(api_key=api_key).audio.transcriptions.create(
            model="whisper-1", file=audio_handle, language="de"
        )
    return str(transcript.text)


