from __future__ import annotations

import json
import os
import threading
import uuid
import zipfile
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import Annotated, Any, NoReturn

from fastapi import FastAPI, File, Form, HTTPException, Request, UploadFile
from fastapi.responses import FileResponse, JSONResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field
from starlette.concurrency import run_in_threadpool

from palantum.export import export_project
from palantum.orchestrator import (
    _schema,
    analyze,
    build_chunk_variants,
    finalize_chunk_variants,
    recommend_chunk_variants,
)
from palantum.state import load
from palantum.web.script import (
    CanvasAgentResponseError,
    CanvasAgentSuggestion,
    CanvasAgentUnavailableError,
    CanvasOrchestrationResult,
    assist_canvas_agent,
    build_canvas_metadata,
    create_script_stream,
    orchestrate_canvas,
    parse_canvas_beats,
)

ROLE_NAMES = {
    "A1": "Script Supervisor",
    "A2": "Director",
    "A3": "Stratege",
    "A4": "Cutter",
    "A5": "Variant Supervisor",
    "A7": "QC",
}
_EXECUTOR = ThreadPoolExecutor(max_workers=1)
_RECOMMENDATION_EXECUTOR = ThreadPoolExecutor(max_workers=2)
_PIPELINE_LOCK = threading.Lock()
_MANIFEST_LOCK = threading.Lock()
_CANVAS_LOCK = threading.Lock()
_JOB_LOCK = threading.Lock()
_VIDEO_SUFFIXES = {".m4v", ".mov", ".mp4", ".webm"}


class CanvasPersistenceError(RuntimeError):
    """Raised when an existing canvas cannot be read without risking data loss."""


def _load_env() -> None:
    """Load the first local .env without ever overriding the process environment."""
    candidates = (Path.cwd() / ".env", Path(__file__).resolve().parents[2] / ".env")
    seen: set[Path] = set()
    for candidate in candidates:
        resolved = candidate.resolve()
    const ghostWords = ghost.trim().split(/\s+/);
    if (ghostWords.length > 1 && ghostWords[0].toLowerCase() === lastWord) {
      ghost = ghostWords.slice(1).join(' ');
    }
  }

  let prefixSpace = '';
  if (before && !before.endsWith(' ') && !before.endsWith('\n') && !ghost.startsWith(' ') && !ghost.startsWith('.') && !ghost.startsWith(',')) {
    prefixSpace = ' ';
  }

  const escapedBefore = escapeHtml(before);
  const escapedGhost = escapeHtml(prefixSpace + ghost);
  const escapedAfter = escapeHtml(after);

  display.innerHTML = `<span>${escapedBefore}</span><span class="ghost-text-grey">${escapedGhost}</span><span>${escapedAfter}</span>`;
  display.classList.add('visible');
  prompt.classList.add('has-ghost');
}

// Dismiss an advice note permanently
function dismissAdvice(event, agentKey) {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  state.dismissed[agentKey] = true;
  const badge = $(`info-badge-${agentKey}`);
  if (badge) {
    badge.style.display = 'none';
  }
}

// Keyboard shortcut: Tab accepts the verbatim grey ghost text directly at caret / replaces targeted rewrite
$('prompt').addEventListener('keydown', event => {
  if (event.key === 'Tab' && state.activeGhostText && $('prompt').selectionStart === $('prompt').selectionEnd) {
    event.preventDefault();
    const prompt = $('prompt');
    const text = prompt.value || '';
    let ghost = state.activeGhostText;

    let insertPos = text.length;
    if (document.activeElement === prompt && typeof prompt.selectionStart === 'number' && prompt.selectionStart < text.length) {
      insertPos = prompt.selectionStart;
    }
  } catch (error) {
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
    $('script-result').hidden = true;
  } finally {
    state.generating = false;
    updateComposer(true);
  }
}

async function uploadVideos(files, brief) {
  const videos = files.filter(f => f.type.startsWith('video/') || /\.(mp4|mov|webm|m4v)$/i.test(f.name));
  if (!videos.length) {
    $('compose-error').textContent = 'Für die Videoerstellung wird mindestens eine Videodatei benötigt.';
    $('compose-error').hidden = false;
    return;
  }
  clearTimeout(state.canvasSaveTimeout);
  if (state.canvasHydrated) await saveCanvas(++state.saveRevision);
  state.uploading = true;
  $('script-result').hidden = true;
  $('progress').hidden = false;
  $('progress-copy').textContent = 'Video wird hochgeladen …';
  $('output').hidden = true;
  $('toolbar').hidden = true;
  showJobStatus({
    tone: 'waiting',
    title: 'Videoauftrag gestartet',
    detail: 'Das Video wird hochgeladen und für die Verarbeitung vorbereitet.',
    eta: 'ca. 6–10 Min.',
    progress: 8,
  });

  const form = new FormData();
  videos.forEach(f => form.append('files', f));
  if (brief) form.append('brief', brief);

  try {
    const response = await fetch('/api/upload', { method: 'POST', body: form });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}));
      throw new Error(payload.detail || payload.error || 'Der Upload ist fehlgeschlagen.');
    }
    poll();
  } catch (error) {
    state.uploading = false;
    $('progress').hidden = true;
    $('toolbar').hidden = false;
    showJobStatus({
      tone: 'error',
      title: 'Upload fehlgeschlagen',
      detail: 'Der Videoauftrag konnte nicht gestartet werden.',
      eta: 'Gestoppt',
      progress: 100,
    });
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

function renderBeats(beats = []) {
  $('beats').innerHTML = beats.map(b => `<span class="beat" data-status="${b.status}">${b.id}</span>`).join('');
}

function validChunkRecommendation(chunk) {
  const recommendation = chunk?.recommendation;
  if (!recommendation || !recommendation.variant_id) return null;
  const status = String(recommendation.status || 'ready').toLowerCase();
  if (['failed', 'error', 'unavailable', 'pending'].includes(status)) return null;
  const variant = (chunk.variants || []).find(item => item.id === recommendation.variant_id);
  return variant ? recommendation : null;
}

function chunkVideoUrl(chunkId, variant) {
  return variant.video_url || `/api/chunks/${encodeURIComponent(chunkId)}/variants/${encodeURIComponent(variant.id)}/video`;
}

function renderChunkReview(chunks = [], selectionComplete = null) {
  state.chunks = Array.isArray(chunks) ? chunks : [];
  const list = $('chunk-list');
  list.innerHTML = '';

  state.chunks.forEach((chunk, index) => {
    const section = document.createElement('article');
    section.className = 'chunk';
    section.dataset.chunkId = chunk.id;

    const head = document.createElement('div');
    head.className = 'chunk-head';
    const heading = document.createElement('div');
    $('compose-error').hidden = false;
  };
  state.recognition = recognition;
  $('mic').classList.add('listening');
  recognition.start();
}

$('prompt').addEventListener('input', () => {
  state.textRevision += 1;
  state.canvas.text = $('prompt').value;
  $('compose-error').hidden = true;
  updateComposer(false);
  queueCanvasSave();
});
$('script-output').addEventListener('input', () => autosize($('script-output')));
$('upload').addEventListener('click', () => $('picker').click());
$('picker').addEventListener('change', event => {
  selectFiles(event.target.files);
  event.target.value = '';
});
$('mic').addEventListener('click', startDictation);
$('generate').addEventListener('click', generateScript);
$('create-video').addEventListener('click', () => uploadVideos(state.files, $('script-output').value.trim() || $('prompt').value.trim()));
$('apply-recommendations').addEventListener('click', applyRecommendations);
$('finalize').addEventListener('click', finalizeVideo);
$('reset').addEventListener('click', () => location.assign(location.pathname));

document.querySelectorAll('.agent-avatar[data-agent-id]').forEach(avatar => {
  const request = () => requestAgentAssist(avatar.dataset.agentId);
  avatar.addEventListener('click', request);
  avatar.addEventListener('keydown', event => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      request();
    }
  });
});

window.addEventListener('resize', updateMirrorDimensions);
document.addEventListener('dragover', event => event.preventDefault());
document.addEventListener('drop', event => {
  event.preventDefault();
  selectFiles(event.dataTransfer.files);
});

window.addEventListener('pagehide', () => {
  if (!state.canvasHydrated) return;
  clearTimeout(state.canvasSaveTimeout);
  fetch('/api/canvas', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(canvasPayload()),
    keepalive: true,
  }).catch(() => {});
});

loadAgentConfig();
loadInitialState().finally(() => updateComposer(true));
</script>
</body>
</html>

